import json,glob,sys,collections
R={}
for f in glob.glob('/tmp/export/*.ndjson'):
    for l in open(f):
        r=json.loads(l); R[r['id']]=r
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
def et(r): return ext(r,'event-time') or r.get('created') or ''
PAT={r['id']:r for r in R.values() if r['resourceType']=='Patient'}
EP=[r for r in R.values() if r['resourceType']=='EpisodeOfCare']
obsbyspec=collections.defaultdict(list)
for r in R.values():
    if r['resourceType']=='Observation' and r.get('specimen'):
        obsbyspec[r['specimen']['reference'].split('/')[-1]].append(r)
basic_by_acc=collections.defaultdict(list)
for r in R.values():
    if r['resourceType']=='Basic': basic_by_acc[ext(r,'accession')].append(r)
pat_by_mrn={r['identifier'][0]['value']:r for r in PAT.values()}
bypat=collections.defaultdict(list)
for r in R.values():
    ref=(r.get('subject') or r.get('patient') or r.get('for') or {}).get('reference','')
    if ref.startswith('Patient/'): bypat[ref[8:]].append(r)

def pid_of(name,mrn,dob):
    p=pat_by_mrn.get(mrn)
    if p and p['birthDate']==dob: return p['id']
    cands=[q['id'] for q in PAT.values() if q['birthDate']==dob and q['name'][0]['text'].upper().replace(',','')==name.replace(',','')]
    return ('MRN=%s/DOB=%s'%(mrn,dob))+ (' name-matches:'+','.join(cands) if cands else '')

def report(pid):
    out=[]
    p=PAT[pid]
    out.append(f"### Patient {pid} MRN {p['identifier'][0]['value']} DOB {p['birthDate']} {p['name'][0]['text']} {p['gender']}")
    eps=[e for e in EP if e['patient']['reference'].endswith(pid)]
    for e in eps: out.append(f"  Episode {e['id']} dx-start {e['period']['start']}")
    rs=sorted(bypat[pid],key=lambda r:(et(r),r['resourceType']))
    # also specimens of this patient already included (subject)
    for r in rs:
        t=r['resourceType']; e=et(r)[:16]
        if t in ('Patient','EpisodeOfCare'): continue
        if t=='Condition':
            out.append(f"  {e} COND {r['id']} {r['code']['text']} by {r.get('recorder',{}).get('display')}")
        elif t=='AllergyIntolerance':
            out.append(f"  {e} ALLERGY {r['id']} {r['code']['text']} {[m['text'] for x in r.get('reaction',[]) for m in x['manifestation']]}")
        elif t=='MedicationAdministration':
            out.append(f"  {e} MEDADMIN {r['id']} {r['medicationCodeableConcept']['text']} {r['status']} {r.get('dosage',{}).get('text')} note={[n['text'] for n in r.get('note',[])]}")
        elif t=='MedicationDispense':
            out.append(f"  {e} MEDDISP {r['id']} {r['medicationCodeableConcept']['text']} {r['status']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} sig={[d['text'] for d in r.get('dosageInstruction',[])]} note={[n['text'] for n in r.get('note',[])]}")
        elif t=='DocumentReference':
            out.append(f"  {e} DOC {r['id']} [{r['type']['text']}/{ext(r,'author-role')}] auth={[a['display'] for a in r.get('author',[])]}\n      {r.get('description','').replace(chr(10),' | ')}")
        elif t=='Task':
            if r['status']=='requested':
                out.append(f"  {e} REQUEST {r['id']} {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference','')[15:]} :: {r.get('description')}")
            else:
                out.append(f"  {e} ITEM {r['id']} {r.get('code',{}).get('coding',[{}])[0].get('code')} {r.get('businessStatus')}")
        elif t=='Specimen':
            lab=(ext(r,'label-name'),ext(r,'label-mrn'),ext(r,'label-dob'))
            obs=obsbyspec.get(r['id'],[])
            note=f"  {e} SPEC {r['id']} acc={r.get('accessionIdentifier',{}).get('value')} label={lab[0]}/{lab[1]}/{lab[2]} collector={r.get('collection',{}).get('collector',{}).get('display')}"
            if lab[1]!=p['identifier'][0]['value'] or lab[2]!=p['birthDate']:
                note+=f" <<LABEL->{pid_of(lab[0] or '',lab[1],lab[2])}>>"
            for ob in obs:
                if not ob['subject']['reference'].endswith(pid):
                    note+=f" <<OBS-IN-CHART-OF {ob['subject']['reference'][8:]} obs={ob['id']} {ob['code']['text']} {ob.get('valueString')}>>"
            out.append(note)
        elif t=='Observation':
            acc=r.get('identifier',[{}])[0].get('value')
            spid=r.get('specimen',{}).get('reference','').split('/')[-1]
            s=R.get(spid)
            line=f"  {e} OBS {r['id']} {r['code']['text']} {r['status']} coll={r.get('effectiveDateTime','')[:16]} issued={r.get('issued','')[:16]} val={r.get('valueString')!r} acc={acc}"
            if r.get('note'): line+=f" NOTE={[n['text'] for n in r['note']]}"
            if s:
                lab=(ext(s,'label-name'),ext(s,'label-mrn'),ext(s,'label-dob'))
                line+=f"\n      spec={spid} subj={s['subject']['reference'][8:]} coll={s.get('collection',{}).get('collectedDateTime','')[:16]} label={lab[0]}/{lab[1]}/{lab[2]} collector={s.get('collection',{}).get('collector',{}).get('display')}"
                if lab[1]!=p['identifier'][0]['value'] or lab[2]!=p['birthDate']:
                    line+=f" <<LABEL->{pid_of(lab[0] or '',lab[1],lab[2])}>>"
                if not s['subject']['reference'].endswith(pid):
                    line+=" <<SPEC-SUBJ-OTHER>>"
            for b in basic_by_acc.get(acc,[]):
                bn=(ext(b,'patient-name'),ext(b,'patient-mrn'),ext(b,'patient-dob'))
                line+=f"\n      accn={b['id']} {bn[0]}/{bn[1]}/{bn[2]} recv={ext(b,'received')[:16]} by {b.get('author',{}).get('display')}"
                if bn[1]!=p['identifier'][0]['value'] or bn[2]!=p['birthDate']:
                    line+=f" <<ACCN->{pid_of(bn[0] or '',bn[1],bn[2])}>>"
            out.append(line)
    return '\n'.join(out)
if __name__=='__main__':
    ids=sys.argv[1:] or sorted(PAT)
    for i in ids: print(report(i)); print()
