R={}
for f in glob.glob('/tmp/export/*.ndjson'):
    for l in open(f):
        r=json.loads(l); R[r['id']]=r
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
def et(r): return ext(r,'event-time') or r.get('created') or ''
PAT={r['id']:r for r in R.values() if r['resourceType']=='Patient'}
EP=[r for r in R.values() if r['resourceType']=='EpisodeOfCare']
basic_by_acc=collections.defaultdict(list)
for r in R.values():
    if r['resourceType']=='Basic': basic_by_acc[ext(r,'accession')].append(r)
key2pid={}
for p in PAT.values(): key2pid[(p['identifier'][0]['value'],p['birthDate'])]=p['id']
bypat=collections.defaultdict(list)
for r in R.values():
    ref=(r.get('subject') or r.get('patient') or r.get('for') or {}).get('reference','')
    if ref.startswith('Patient/'): bypat[ref[8:]].append(r)
D=lambda s: datetime.date.fromisoformat(s[:10])
EVAL=D('2026-09-24')

def owner(ob):
    """returns (ownerpid or 'UNRESOLVED', detail)"""
    sp=R.get(ob.get('specimen',{}).get('reference','').split('/')[-1])
    acc=ob.get('identifier',[{}])[0].get('value')
    bs=basic_by_acc.get(acc,[])
    k1=(ext(sp,'label-mrn'),str(ext(sp,'label-dob'))) if sp else None
    ks=[k1]+[(ext(b,'patient-mrn'),str(ext(b,'patient-dob'))) for b in bs]
    uniq=set(ks)
    d=f"spec_label={k1} accn={[(ext(b,'patient-mrn'),str(ext(b,'patient-dob'))) for b in bs]}"
    if len(uniq)==1:
        return key2pid.get(list(uniq)[0],'UNKNOWN'+str(list(uniq)[0])), d
    return 'UNRESOLVED', d

rpr_owned=collections.defaultdict(list)   # pid -> list of obs
for r in R.values():
    if r['resourceType']=='Observation' and r['code']['text'].startswith('RPR'):
        o,d=owner(r)
        rpr_owned[o].append(r)

STAGE_FU={'Primary syphilis':[6,12],'Secondary syphilis':[6,12],'Early latent syphilis':[6,12,24],
          'Late latent syphilis':[6,12,24],'Latent syphilis, unknown duration':[6,12,24]}
def addm(d,m):
    y=d.year+(d.month-1+m)//12; mo=(d.month-1+m)%12+1
    day=min(d.day,[31,29 if y%4==0 and (y%100!=0 or y%400==0) else 28,31,30,31,30,31,31,30,31,30,31][mo-1])
    return datetime.date(y,mo,day)

out=[]
for pid,p in sorted(PAT.items()):
    rs=bypat[pid]
    eps=[e for e in EP if e['patient']['reference'].endswith(pid)]
    conds=[r for r in rs if r['resourceType']=='Condition']
    meds=[r for r in rs if r['resourceType']=='MedicationAdministration']
    disp=[r for r in rs if r['resourceType']=='MedicationDispense']
    docs=[r for r in rs if r['resourceType']=='DocumentReference']
    bic=sorted(D(m['effectiveDateTime']) for m in meds if m['status']=='completed' and 'icillin' in m['medicationCodeableConcept']['text'])
    stages=[c['code']['text'] for c in sorted(conds,key=et)]
    dx=D(eps[0]['period']['start'])
    lines=[f"{pid} dx={dx} stage={stages} doses={[str(x) for x in bic]} notdone={[et(m)[:10] for m in meds if m['status']!='completed']} other={[m['medicationCodeableConcept']['text']+'@'+et(m)[:10] for m in meds if 'icillin' not in m['medicationCodeableConcept']['text']]} disp={[d['medicationCodeableConcept']['text']+'@'+et(d)[:10] for d in disp]}"]
    # RPRs owned
    ow=sorted(rpr_owned.get(pid,[]),key=lambda o:o.get('effectiveDateTime',''))
    lines.append("  ownedRPR: "+'; '.join(f"{o.get('effectiveDateTime','')[:10]} {o['status']} {o.get('valueString')} chart={o['subject']['reference'][8:]}{'*' if not o['subject']['reference'].endswith(pid) else ''}{' NOTE:'+str([n['text'] for n in o.get('note',[])]) if o.get('note') else ''}" for o in ow))
    # RPRs filed in chart
    inchart=[o for o in rs if o['resourceType']=='Observation' and o['code']['text'].startswith('RPR')]
    for o in inchart:
        ow2,d=owner(o)
        if ow2!=pid:
            lines.append(f"  FOREIGN/UNRESOLVED RPR in chart: {o['id']} coll={o.get('effectiveDateTime','')[:10]} {o['status']} {o.get('valueString')} owner={ow2} {d}")
    # other obs in chart with mismatch
    for o in rs:
        if o['resourceType']=='Observation' and not o['code']['text'].startswith('RPR'):
            ow2,d=owner(o)
            if ow2!=pid: lines.append(f"  FOREIGN/UNRESOLVED other obs: {o['id']} {o['code']['text']} coll={o.get('effectiveDateTime','')[:10]} owner={ow2} {d}")
    # follow-up windows
    if bic and stages:
        st=stages[-1]
        for m in STAGE_FU.get(st,[]):
            due=addm(bic[0],m); lo=due-datetime.timedelta(days=30); hi=due+datetime.timedelta(days=30)
            got=[o for o in ow if o.get('effectiveDateTime') and lo<=D(o['effectiveDateTime'])<=hi]
            unres=[o for o in rpr_owned.get('UNRESOLVED',[]) if o.get('effectiveDateTime') and lo<=D(o['effectiveDateTime'])<=hi and (o['subject']['reference'].endswith(pid) or True)]
            st2='OPEN' if hi>=EVAL else 'CLOSED'
            desc=[f"{o.get('effectiveDateTime','')[:10]}/{o['status']}" for o in got]
            lines.append(f"  FU {m}mo due={due} win={lo}..{hi} {st2} collected={desc}")
    prg=[]
    for o in rs:
        if o['resourceType']=='Observation' and 'hCG' in o['code']['text']:
            prg.append(f"hCG@{o.get('effectiveDateTime','')[:10]}={o.get('valueString')}/{o['status']}")
    for d in docs:
        if re.search(r'pregn|gestat|prenat|delive|postpart|EDD|weeks|LMP|\d+w\d+d|trimester|lactat|breastfeed|baby|newborn|infant',d.get('description',''),re.I) or d['type']['text'] in ('Prenatal visit','Postpartum visit','Prenatal intake'):
            prg.append(f"DOC {d['id']}[{d['type']['text']}]@{et(d)[:10]}")
    if prg: lines.append("  PREG: "+'; '.join(prg))
    out.append('\n'.join(lines))
print('\n'.join(out))
